Translate("frFR", "teldrassil", {
	title = "Teldrassil",
	sections = {
		{
			title = "Résumé",
			text = [=[Teldrassil est le nouvel Arbre-monde des {link:night-elves}elfes de la nuit{/link}, et la terre qui pousse sur lui. Il s'élève de la mer au large de la côte nord de {link:kalimdor}Kalimdor{/link}, si vaste que des forêts, des lacs et des villages entiers reposent sur ses branches. À sa cime se dresse la cité de {link:darnassus}Darnassus{/link}. Ses clairières sont éclairées par des puits de lune et gardées par les {link:sentinels}Sentinelles{/link}, et pour un nouveau venu, c'est le lieu le plus paisible du monde. Ceux qui y vivent savent qu'il n'en est rien. Quelque chose ne va pas avec l'arbre, et chaque saison, les signes deviennent plus difficiles à ignorer.]=],
		},
		{
			title = "L'Arbre-monde",
			text = [=[Après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, les elfes de la nuit se retrouvèrent privés de leur force d'antan. {link:nordrassil}Nordrassil{/link} avait dépensé sa puissance pour détruire {link:archimonde}Archimonde{/link}, et avec elle les Kaldorei perdirent leur immortalité. {link:malfurion-stormrage}Malfurion Stormrage{/link} entra dans le {link:emerald-dream}Rêve d'émeraude{/link} et ne revint pas. En son absence, l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} prit la tête des druides. Il persuada le Cercle des Anciens, en {link:darkshore}Sombrivage{/link}, que le temps était venu de reconstruire et de reconquérir ce qui avait été perdu. Avec l'accord du Cercle, lui et les plus puissants druides de son ordre firent pousser un nouvel arbre au-delà de la côte.

Quand il eut grandi, Fandral demanda aux grands dragons de le bénir, comme ils avaient jadis béni Nordrassil. Nozdormu, seigneur du Temps, le refusa et blâma son orgueil. {link:alexstrasza}Alexstrasza{/link}, la Lieuse-de-vie, le refusa aussi. Privée de leurs dons, la croissance de Teldrassil a été imparfaite et imprévisible, et les elfes de la nuit n'ont pas retrouvé leur vie éternelle.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Teldrassil abrite la plupart des Kaldorei qui survécurent à la guerre. Jeunes druides, prêtresses et {link:sentinels}Sentinelles{/link} commencent leur service à {link:shadowglen}Sombrevallon{/link} et à {link:dolanaar}Dolanaar{/link}, puis montent jusqu'à {link:darnassus}Darnassus{/link}. Pourtant, la forêt est malade. Les furbolgs {link:gnarlpine-furbolgs}Pins-tordus{/link}, autrefois doux amis des elfes, sont devenus sauvages. Des sylvains surgissent du sol, furieux et couverts de tumeurs. Des harpies nichent autour de l'arbre de l'Oracle, des satyres se cachent dans ses grottes, et une gangremousse se répand chez les bêtes comme chez les furbolgs. Les druides étudient chaque nouveau mal à son tour. L'archidruide porte le poids de tout cela, et il ne le porte pas à la légère.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les elfes de la nuit.{/b} Druides, prêtresses d'Elune, {link:sentinels}Sentinelles{/link}, chasseurs et artisans, vivant dans des villages tissés parmi les arbres.
• {b}Les furbolgs {link:gnarlpine-furbolgs}Pins-tordus{/link}.{/b} Une tribu devenue folle, qui lance ses raids depuis le {link:gnarlpine-hold}Camp des Pins-tordus{/link} et les refuges des saisons.
• {b}Sylvains et grells.{/b} Des créatures de l'arbre lui-même, dont beaucoup sont corrompues.
• {b}Les harpies Bloodfeather.{/b} Elles nichent dans les clairières de l'ouest.
• {b}Les satyres.{/b} Quelques-uns de ces elfes déchus rôdent dans des lieux cachés.]=],
		},
		{
			title = "Légendes de l'arbre",
			text = [=[• Les puits de lune de Teldrassil contiennent des eaux tirées de l'antique {link:well-of-eternity}puits d'Éternité{/link}. Les druides s'en servent, les {link:sentinels}Sentinelles{/link} les vénèrent comme des sanctuaires d'Elune, et toute sorcellerie est interdite à leurs abords.
• Le plus ancien et le plus puissant des puits de lune se trouve sous l'arbre de l'Oracle, qui parle aux anciens des Kaldorei à sa manière lente.
• Des plantes jamais vues sur l'arbre auparavant y ont germé, certaines venues de terres aussi lointaines que le {link:swamp-of-sorrows}Marais des Chagrins{/link}, et elles réagissent étrangement avec son sol.]=],
		},
	},
})

Translate("frFR", "shadowglen", {
	title = "Sombrevallon",
	sections = {
		{
			title = "Résumé",
			text = [=[Sombrevallon est un vallon abrité au nord-est de {link:teldrassil}Teldrassil{/link}, où beaucoup de jeunes Kaldorei font leurs premiers pas au service de leur peuple. En son cœur pousse le grand arbre {link:aldrassil}Aldrassil{/link}, et un puits de lune brille au nord de celui-ci. Le conservateur {link:conservator-ilthalaine}Ilthalaine{/link} y maintient l'équilibre des bêtes. Le vallon n'est pas aussi sûr qu'il en a l'air. Des grells souillés par la gangremousse errent à sa lisière ouest, là où les {link:gnarlpine-furbolgs}Pins-tordus{/link} vivaient autrefois en paix. Au nord du vallon s'ouvre la Grotte de Sombrefil, où des araignées Tisse-bois, devenues énormes sur l'Arbre-monde, tissent leurs nids.]=],
		},
	},
})

Translate("frFR", "aldrassil", {
	title = "Aldrassil",
	sections = {
		{
			title = "Résumé",
			text = [=[Aldrassil est le grand arbre au centre de {link:shadowglen}Sombrevallon{/link}, creusé et façonné pour devenir la demeure des maîtres des jeunes. Des maîtres de toutes les vocations ont leurs chambres le long de ses rampes sinueuses. Dans sa plus haute salle siège {link:tenaron-stormgrip}Tenaron Stormgrip{/link}, qui envoie chaque nouveau venu puiser de l'eau au puits de lune voisin et commence ainsi le récit de l'histoire de {link:teldrassil}Teldrassil{/link}. L'érudit {link:gilshalan-windwalker}Gilshalan Windwalker{/link} travaille à son pied, et étudie les araignées de la Grotte de Sombrefil.]=],
		},
	},
})

Translate("frFR", "dolanaar", {
	title = "Dolanaar",
	sections = {
		{
			title = "Résumé",
			text = [=[Dolanaar est le village de la route, à mi-chemin entre {link:shadowglen}Sombrevallon{/link} et {link:darnassus}Darnassus{/link}. Ses maisons ont poussé dans le bois vivant autour d'un puits de lune, où {link:corithras-moonrage}Corithras Moonrage{/link} poursuit le récit que {link:tenaron-stormgrip}Tenaron{/link} a commencé. L'aubergiste Keldamyr offre le repos aux voyageurs. Des druides comme {link:athridas-bearmantle}Athridas Bearmantle{/link} et {link:tallonkai-swiftroot}Tallonkai Swiftroot{/link} surveillent d'ici les troubles de la forêt, et la sentinelle {link:sentinel-kyra-starsong}Kyra Starsong{/link} envoie ses sœurs sur les routes. Dolanaar est fier de sa bonne réputation, et ses habitants préfèrent garder certaines hontes pour eux.]=],
		},
	},
})

Translate("frFR", "fel-rock", {
	title = "Gangreroche",
	sections = {
		{
			title = "Résumé",
			text = [=[Gangreroche est une grotte juste au nord de {link:dolanaar}Dolanaar{/link}. Son nom est devenu une dure vérité. Le {link:satyrs}satyre{/link} seigneur {link:lord-melenas}Melenas{/link} établit son repaire dans ses profondeurs et rassembla autour de lui une bande de guerriers grells. Les druides de Dolanaar tiennent pour une profonde honte qu'une telle créature demeure si près de leur village, et ils ont tenté de régler son cas discrètement. On sait désormais que ses complots servaient un maître plus sombre, ailleurs dans la forêt.]=],
		},
	},
})

Translate("frFR", "lake-al-ameth", {
	title = "Lac Al'Ameth",
	aliases = { "Al'Ameth" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Al'Ameth s'étend au sud de {link:dolanaar}Dolanaar{/link}, une longue étendue d'eau bordée d'arbres et de frondes. Sur sa rive orientale, le druide {link:denalan}Denalan{/link} tient un camp et un jardin, où il essaie de nouvelles terres sur les graines des sylvains. C'est au lac que la maladie de ces créatures est la plus visible. De jeunes sylvains poussent à l'état sauvage le long de ses berges, et dans une grotte de sa rive sud demeure {link:oakenscowl}Oakenscowl{/link}, autrefois chef des siens et désormais source de la corruption.]=],
		},
	},
})

Translate("frFR", "starbreeze-village", {
	title = "Brise-stellaire",
	aliases = { "Brise-stellaire" },
	sections = {
		{
			title = "Résumé",
			text = [=[Brise-stellaire se trouve à l'est de {link:teldrassil}Teldrassil{/link}, au-delà de la route de {link:dolanaar}Dolanaar{/link}. C'était un lieu paisible, et un puits de lune brille encore juste à l'extérieur. Puis les {link:gnarlpine-furbolgs}Pins-tordus{/link} arrivèrent. Les furbolgs tendirent une embuscade au gardien {link:gaerolas-talvethren}Gaerolas Talvethren{/link} sur le chemin du refuge des saisons et pillèrent le village. Des maisons sont vides, et les trésors de leurs propriétaires sont restés dans les commodes. Les furbolgs qui demeurent à Brise-stellaire se sont entièrement livrés à leur folie.]=],
		},
	},
})

Translate("frFR", "ban-ethil-barrow-den", {
	title = "Refuge des saisons de Ban'ethil",
	aliases = { "Ban'ethil" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge des saisons de Ban'ethil se trouve à l'ouest de {link:dolanaar}Dolanaar{/link}, sous les racines de la forêt. Ici dorment les druides de la Serre, leurs esprits parcourant le {link:emerald-dream}Rêve d'émeraude{/link} selon leur pacte avec Ysera. Les {link:gnarlpine-furbolgs}Pins-tordus{/link} y ont fait irruption. Leurs chamans ont appris à séparer l'esprit d'un druide endormi de son corps et à lancer la chair vide contre les intrus. Les dormeurs ne peuvent être réveillés qu'avec les reliques de l'éveil, gardées dans des coffres sacrés à l'intérieur. Même des messagers de l'arbre de l'Oracle ont été traînés en bas.]=],
		},
	},
})

Translate("frFR", "gnarlpine-hold", {
	title = "Camp des Pins-tordus",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp des Pins-tordus est la place forte des furbolgs {link:gnarlpine-furbolgs}Pins-tordus{/link}, au sud-ouest de {link:teldrassil}Teldrassil{/link}. Ici demeure leur chef, {link:ursal-the-mauler}Ursal le Mutileur{/link}, qui pousse son peuple à la folie grâce aux pouvoirs de la gangremousse. Chamans, totémiques et défenseurs de la tribu s'entassent dans ses tanières, et des druides capturés y sont retenus sous l'emprise des furbolgs. Ce qui était jadis le foyer d'un peuple paisible est devenu le cœur de la rage de la tribu.]=],
		},
	},
})

Translate("frFR", "pools-of-arlithrien", {
	title = "Bassins d'Arlithrien",
	aliases = { "Arlithrien" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Bassins d'Arlithrien s'étendent au sud-est de la route qui mène à {link:darnassus}Darnassus{/link}, un chapelet d'eaux paisibles à côté de l'un des puits de lune de {link:teldrassil}Teldrassil{/link}. Autrefois, les {link:sentinels}Sentinelles{/link} les patrouillaient sans peine. Désormais, les furbolgs {link:gnarlpine-furbolgs}Pins-tordus{/link} frappent chaque patrouille, et le chemin du puits est dangereux pour quiconque s'y rend seul. Les premiers rapports sur leurs attaques ici furent écartés comme de simples rumeurs. Personne ne les écarte plus.]=],
		},
	},
})

Translate("frFR", "the-oracle-glade", {
	title = "La Clairière de l'Oracle",
	aliases = { "Clairière de l'Oracle" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Clairière de l'Oracle se trouve au nord-ouest de {link:teldrassil}Teldrassil{/link}. En son cœur pousse l'arbre de l'Oracle, qui veille sur la croissance de l'Arbre-monde et envoie ses conseils aux anciens des Kaldorei. Sous ses branches se trouve le premier et le plus puissant puits de lune de Teldrassil. Des harpies Bloodfeather ont niché tout autour de {link:moonglade}la clairière{/link}, et elles ont tué les coursières qui portaient les messages de l'arbre. Une petite troupe de {link:sentinels}Sentinelles{/link} menée par {link:sentinel-arynia-cloudsbreak}Arynia Cloudsbreak{/link} défend le puits de lune contre elles.]=],
		},
	},
})

Translate("frFR", "wellspring-lake", {
	title = "Lac d'Aigue-vive",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac d'Aigue-vive s'étend à l'extrême nord de {link:teldrassil}Teldrassil{/link}, et l'Aigue-vive en part pour traverser la forêt. Les sylvains qui errent sur ses rives sont les plus souillés de l'arbre, couverts de tumeurs moussues pleines de poison. Sur les confins nord voisins demeure dame {link:lady-sathrah}Sathrah{/link}, une grande araignée autrefois aimée d'Elune, dont les fils d'argent recueillaient la rosée guérisseuse du soir. Elle est devenue folle, et les siens avec elle.]=],
		},
	},
})

Translate("frFR", "the-cleft", {
	title = "La Faille",
	sections = {
		{
			title = "Résumé",
			text = [=[La Faille est un pli profond de la forêt, au nord-ouest de {link:dolanaar}Dolanaar{/link}. Peu y vont de leur plein gré. Le {link:satyrs}satyre{/link} Xethorr le Malfaisant en a fait sa demeure, et c'est sur son ordre que le seigneur {link:lord-melenas}Melenas{/link} complotait à {link:fel-rock}Gangreroche{/link}. Xethorr a plié les araignées de {link:teldrassil}Teldrassil{/link} à sa volonté, et les Tisse-bois souillées de la Faille portent la gangremousse dans leur venin. Les druides de Dolanaar préféreraient le chasser en silence plutôt que de laisser la forêt apprendre à quel point il demeure près.]=],
		},
	},
})

Translate("frFR", "rut-theran-village", {
	title = "Rut'theran",
	aliases = { "Rut'theran" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rut'theran se trouve au pied de {link:teldrassil}Teldrassil{/link}, sur le rivage où ses grandes racines rencontrent la mer. C'est la porte de l'arbre sur le monde. Navires et hippogriffes vont et viennent d'ici, et le maître des hippogriffes Vesprystus transporte les voyageurs par-delà les eaux jusqu'à {link:auberdine}Auberdine{/link}, en {link:darkshore}Sombrivage{/link}. Un portail élève jusqu'à la cité ceux qui se rendent à {link:darnassus}Darnassus{/link}. Les poissons de ces eaux sont grands et abondants, et les maîtres du savoir du {link:cenarion-circle}Cercle cénarien{/link} y ont aussi une petite maison.]=],
		},
	},
})

Translate("frFR", "conservator-ilthalaine", {
	title = "Conservateur Ilthalaine",
	subtitle = "Gardien de l'équilibre de Sombrevallon",
	found = "Devant Aldrassil, à Sombrevallon",
	hint = [=[Parlez au conservateur qui se tient devant le grand arbre de Sombrevallon.]=],
	allegiance = "Elfes de la nuit · Sombrevallon",
	aliases = { "Ilthalaine" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le conservateur Ilthalaine maintient l'équilibre de la nature à {link:shadowglen}Sombrevallon{/link}. Les pluies de printemps furent abondantes cette année, et certaines bêtes du vallon prospérèrent tandis que d'autres moururent de faim. Les sabres-de-nuit et les sangliers des chardons sont devenus trop nombreux pour que la terre les nourrisse. Ilthalaine n'aime pas la réponse, mais il la donne sans détour : leur nombre doit être réduit.]=],
		},
		{
			title = "Importance",
			text = [=[Ilthalaine enseigne la première leçon des Kaldorei : tuer peut servir la forêt vivante, quand on le fait pour l'équilibre et non pour le profit.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes de {link:shadowglen}Sombrevallon{/link} réduire le nombre des sabres-de-nuit et des sangliers des chardons.
• Il dirige chaque nouveau venu vers le maître de sa vocation, dans {link:aldrassil}Aldrassil{/link}.]=],
		},
	},
	mentions = {
		{ text = "L'équilibre de la nature" },
		{ text = "L'équilibre de la nature" },
	},
	bonds = {
		{ id = "melithar-staghelm", name = "Melithar Staghelm", note = "veille sur le même vallon" },
		{ id = "tarindrella", name = "Tarindrella", note = "une gardienne des mêmes bois" },
	},
})

Translate("frFR", "melithar-staghelm", {
	title = "Melithar Staghelm",
	subtitle = "Druide de Sombrevallon",
	found = "Près du puits de lune, devant Aldrassil",
	hint = [=[Parlez au druide qui entend les murmures des esprits de la forêt à Sombrevallon.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Melithar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Melithar Staghelm est un druide de {link:shadowglen}Sombrevallon{/link} qui écoute les murmures des esprits de la forêt. Par eux, il apprit que la dryade {link:tarindrella}Tarindrella{/link} était revenue dans le vallon, alors qu'on ne l'avait plus sentie dans les forêts de {link:kalimdor}Kalimdor{/link} depuis des années. Il y vit aussitôt le signe que quelque chose n'allait pas.]=],
		},
		{
			title = "Importance",
			text = [=[Melithar est souvent le premier à envoyer les nouveaux venus vers la dryade, et donc vers la première preuve de la maladie de la forêt.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il annonce le retour de {link:tarindrella}Tarindrella{/link} et demande qu'on la cherche au sud-ouest d'{link:aldrassil}Aldrassil{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Melithar porte le nom de famille de l'archidruide. Aucune chronique ne dit si les deux sont parents, ni comment.]=],
		},
	},
	mentions = {
		{ text = "Le protecteur des bois" },
	},
	bonds = {
		{ id = "tarindrella", name = "Tarindrella", note = "la dryade dont il a senti le retour" },
		{ id = "conservator-ilthalaine", name = "Conservateur Ilthalaine", note = "sert le même vallon" },
	},
})

Translate("frFR", "tarindrella", {
	title = "Tarindrella",
	subtitle = "La protectrice des bois",
	found = "Au sud-ouest d'Aldrassil, à Sombrevallon",
	hint = [=[Cherchez la dryade qui est revenue dans les clairières au sud-ouest d'Aldrassil.]=],
	allegiance = "Les esprits de la forêt",
	sections = {
		{
			title = "Résumé",
			text = [=[Tarindrella est une dryade, une mystérieuse protectrice des bois, qui est revenue à {link:shadowglen}Sombrevallon{/link} après de nombreuses années d'absence. Elle est venue parce que quelque chose de maléfique se prépare dans la forêt. Les grells et les grellins du vallon sont tombés sous l'emprise de la gangremousse, et les paisibles furbolgs des collines ont quitté leurs foyers.]=],
		},
		{
			title = "Importance",
			text = [=[C'est Tarindrella qui, la première, désigna la gangremousse comme la cause de la folie qui se répand parmi les créatures de {link:teldrassil}Teldrassil{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle prouve que les grells de {link:shadowglen}Sombrevallon{/link} portent la gangremousse.
• Elle avertit du danger {link:athridas-bearmantle}Athridas Bearmantle{/link}, à {link:dolanaar}Dolanaar{/link}.
• Elle lit les totems laissés dans les camps abandonnés des {link:gnarlpine-furbolgs}Pins-tordus{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les totems gravés",
			hint = [=[Fouillez les camps abandonnés des Pins-tordus pour trouver leurs totems.]=],
			text = [=[Les furbolgs abandonnèrent leurs totems dans le chaos de leur fuite. Leurs gravures racontaient une sombre histoire. Les {link:gnarlpine-furbolgs}Pins-tordus{/link} avaient commencé à rêver qu'une grande ombre les anéantissait. La peur se changea en rage, et l'ombre de leurs rêves prit la forme de leurs vieux amis, les elfes.]=],
		},
	},
	mentions = {
		{ text = "Le protecteur des bois" },
		{ text = "L'appel de la nature" },
	},
	bonds = {
		{ id = "melithar-staghelm", name = "Melithar Staghelm", note = "a senti son retour" },
		{ id = "athridas-bearmantle", name = "Athridas Bearmantle", note = "le druide à qui elle envoie de l'aide" },
		{ id = "gnarlpine-furbolgs", name = "Furbolgs Pins-tordus", note = "la tribu dont elle étudie la chute" },
	},
})

Translate("frFR", "gilshalan-windwalker", {
	title = "Gilshalan Windwalker",
	subtitle = "Érudit des araignées Tisse-bois",
	found = "Au pied d'Aldrassil, à Sombrevallon",
	hint = "Parlez à l'érudit qui étudie les araignées de Sombrevallon.",
	allegiance = "Elfes de la nuit · Darnassus",
	aliases = { "Gilshalan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Gilshalan Windwalker est venu à {link:shadowglen}Sombrevallon{/link} pour étudier les araignées Tisse-bois de la Grotte de Sombrefil. Elles sont cousines d'une espèce bien plus petite, et il croit que l'Arbre-monde les a changées. Il veut que leur venin et leurs œufs soient portés à {link:darnassus}Darnassus{/link}, où il pourra les comparer à leurs cousines plus petites. Il est assez honnête pour admettre qu'une araignée géante vivante serait plus qu'il ne pourrait en maîtriser.]=],
		},
		{
			title = "Importance",
			text = [=[Les études de Gilshalan comptent parmi les premières tentatives de comprendre ce que le nouvel arbre fait aux créatures qui vivent sur lui.]=],
		},
		{
			title = "Hauts faits",
