			hint = "Rapportez à Arynia les amulettes des chefs des harpies.",
			text = [=[Arynia vit une noirceur parcourir les ceintures des harpies. Les amulettes de leurs chefs montraient des volutes vertes à l'intérieur des gemmes. C'était la gangremousse, la même souillure que celle signalée à {link:shadowglen}Sombrevallon{/link}, et elle prévint ses supérieures.]=],
		},
	},
	mentions = {
		{ text = "La clairière enchantée" },
		{ text = "{link:teldrassil}Teldrassil{/link}" },
		{ text = "Mist" },
		{ text = "Ténèbres dans {link:moonglade}la clairière{/link}" },
		{ text = "L'arbre de l'Oracle" },
