Translate("frFR", "gnarlpine-furbolgs", {
	title = "Furbolgs Pins-tordus",
	aliases = { "Pins-tordus", "tribu des Pins-tordus" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Pins-tordus sont une tribu de {link:furbolgs}furbolgs{/link} qui vivaient dans les collines de {link:teldrassil}Teldrassil{/link} en paisibles amis des elfes de la nuit. Ils ont déserté leurs anciens foyers et se sont rassemblés sous leur chef, {link:ursal-the-mauler}Ursal le Mutileur{/link}, et ils attaquent désormais les protecteurs mêmes en qui ils avaient autrefois confiance.]=],
		},
		{
			title = "La chute de la tribu",
			text = [=[La dryade {link:tarindrella}Tarindrella{/link} croit que seule la gangremousse a pu causer un tel changement. {link:ursal-the-mauler}Ursal{/link} utilise ses pouvoirs pour rendre son peuple fou. Les totems laissés dans leurs camps abandonnés en disent davantage. Les Pins-tordus commencèrent à rêver d'une grande ombre qui les détruirait. Leur peur se changea en rage, et l'ombre de leurs rêves devint leurs amis elfes.]=],
		},
		{
			title = "Hauts faits de la folie",
			text = [=[• Ils tendirent une embuscade au gardien {link:gaerolas-talvethren}Gaerolas Talvethren{/link} et pillèrent {link:starbreeze-village}Brise-stellaire{/link}.
• Ils firent irruption dans le {link:ban-ethil-barrow-den}Refuge des saisons de Ban'ethil{/link}, et leurs chamans apprirent à séparer l'esprit d'un druide endormi de son corps.
• Ils s'attaquent à la route de {link:darnassus}Darnassus{/link} et aux patrouilles des {link:pools-of-arlithrien}Bassins d'Arlithrien{/link}.
• Leur mystique Ferocitas le Mangeur de rêves vola une émeraude qui puisait sa puissance dans le Rêve.]=],
		},
		{
			title = "Non consigné",
			text = [=[Personne ne sait encore d'où vient la gangremousse, ni si les furbolgs peuvent être guéris.]=],
		},
	},
})

Translate("frFR", "corruption-of-teldrassil", {
	title = "Corruption de Teldrassil",
	sections = {
		{
			title = "Résumé",
			text = [=[La corruption de {link:teldrassil}Teldrassil{/link} est la maladie qui s'est répandue dans le nouvel Arbre-monde depuis qu'il a poussé. Les prêtresses et les druides en voient les signes partout : chez les bêtes, dans les plantes, chez les furbolgs et jusque dans le sol.]=],
		},
		{
			title = "Signes",
			text = [=[• D'étranges bêtes surgissent du sol même de l'arbre, et les sylvains deviennent furieux et enflés de tumeurs venimeuses.
• Une gangremousse souille les grells de {link:shadowglen}Sombrevallon{/link}, les harpies de la {link:the-oracle-glade}Clairière de l'Oracle{/link} et les furbolgs {link:gnarlpine-furbolgs}Pins-tordus{/link}.
• Le {link:satyrs}satyre{/link} Xethorr le Malfaisant a corrompu les araignées de l'arbre, et d'autres satyres profanent ses puits de lune.
• {link:lady-sathrah}Dame Sathrah{/link}, une araignée aimée d'Elune, est devenue folle.
• Des plantes de terres lointaines germent sur l'arbre et réagissent étrangement avec son sol.]=],
		},
		{
			title = "La question de la cause",
			text = [=[{link:corithras-moonrage}Corithras Moonrage{/link} attribue bien des maux de l'arbre au fait qu'il poussa sans la bénédiction de Nozdormu et d'{link:alexstrasza}Alexstrasza{/link}. {link:fandral-staghelm}Fandral Staghelm{/link} porte le fardeau de trouver un remède, et il craint que son œuvre ne soit jamais achevée. Les druides de {link:moonglade}Reflet-de-Lune{/link} et ceux de {link:darnassus}Darnassus{/link} se méfient les uns des autres, et la corruption qui persiste n'apaise en rien cette méfiance.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne nomme encore la source de la gangremousse ni n'explique comment la souillure entra d'abord dans l'arbre.]=],
		},
	},
})
